ROOT = Path(DATA_DIR)
NY = ZoneInfo("America/New_York")
UTC = timezone.utc

rows = []


def to_utc(dt):
    if dt is None:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=NY)
    return dt.astimezone(UTC)


def local_midnight(d):
    if isinstance(d, str):
        d = date.fromisoformat(d)
    return datetime.combine(d, time(0, 0), tzinfo=NY).astimezone(UTC)


def parse_apple_dt(s):
    if not s:
        return None
    return datetime.strptime(s, "%Y-%m-%d %H:%M:%S %z").astimezone(UTC)


def parse_iso_dt(s):
    if not s:
        return None
    return datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(UTC)


def parse_local_dt(date_s, time_s=None):
    if time_s is None:
        dt = datetime.strptime(date_s, "%Y-%m-%d")
    else:
        dt = datetime.strptime(f"{date_s} {time_s}", "%Y-%m-%d %I:%M %p")
    return dt.replace(tzinfo=NY).astimezone(UTC)


def parse_month_name_dt(s):
    return datetime.strptime(s.strip(), "%B %d, %Y, %I:%M %p").replace(tzinfo=NY).astimezone(UTC)


def ts_local_date(ts):
    return ts.astimezone(NY).date() if ts else None


def num(x):
    if x is None or x == "":
        return None
    try:
        return float(x)
    except Exception:
        return None


def intval(x):
    v = num(x)
    return int(v) if v is not None and not math.isnan(v) else None


def clean_name(s):
    if s is None:
        return None
    s = str(s)
    for prefix in ["HKQuantityTypeIdentifier", "HKWorkoutActivityType", "HKCategoryTypeIdentifier", "HK"]:
        if s.startswith(prefix):
            s = s[len(prefix):]
    s = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", s)
    s = re.sub(r"[^A-Za-z0-9]+", "_", s).strip("_").lower()
    return s


def base_row(ts, source_file, source, record_type, observation_id=None, interval_start=None, interval_end=None, inferred=False):
    return {
        "timestamp": ts,
        "local_date": ts_local_date(ts),
        "timestamp_inferred": bool(inferred),
        "source_file": source_file,
        "source": source,
        "record_type": record_type,
        "observation_id": observation_id,
        "interval_start": interval_start,
        "interval_end": interval_end,
    }


def text_between_sections(block, section_name):
    pat = re.compile(rf"^### {re.escape(section_name)}\s*\n\n(.*?)(?=^### |\Z)", re.M | re.S)
    m = pat.search(block)
    return m.group(1).strip() if m else None


def compact_text(s):
    if s is None:
        return None
    return re.sub(r"\s+", " ", s).strip()


