# ICS calendar events with recurrence expansion.
def unfold_ics(text):
    out = []
    for line in text.splitlines():
        if line.startswith((" ", "\t")) and out:
            out[-1] += line[1:]
        else:
            out.append(line)
    return out


def parse_params(prop):
    parts = prop.split(";")
    name = parts[0].upper()
    params = {}
    for part in parts[1:]:
        if "=" in part:
            k, v = part.split("=", 1)
            params[k.upper()] = v
    return name, params


def parse_ics_dt(value, params):
    if params.get("VALUE") == "DATE" or re.fullmatch(r"\d{8}", value):
        d = datetime.strptime(value, "%Y%m%d").date()
        return local_midnight(d), True
    if value.endswith("Z"):
        return datetime.strptime(value, "%Y%m%dT%H%M%SZ").replace(tzinfo=UTC), False
    tz = ZoneInfo(params.get("TZID", "America/New_York"))
    return datetime.strptime(value, "%Y%m%dT%H%M%S").replace(tzinfo=tz).astimezone(UTC), False


def parse_rrule(rule):
    d = {}
    for part in (rule or "").split(";"):
        if "=" in part:
            k, v = part.split("=", 1)
            d[k.upper()] = v
    return d


def weekday_num(code):
    return {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}[code]


def nth_weekday(year, month, token):
    m = re.fullmatch(r"(-?\d)?([A-Z]{2})", token)
    if not m:
        return None
    n = int(m.group(1) or 1)
    wd = weekday_num(m.group(2))
    if n > 0:
        d = date(year, month, 1)
        shift = (wd - d.weekday()) % 7
        return d + timedelta(days=shift + 7 * (n - 1))
    if month == 12:
        d = date(year + 1, 1, 1) - timedelta(days=1)
    else:
        d = date(year, month + 1, 1) - timedelta(days=1)
    shift = (d.weekday() - wd) % 7
    return d - timedelta(days=shift + 7 * ((-n) - 1))


def parse_duration_minutes(s):
    if not s:
        return None
    s = s.strip().lower()
    total = 0.0
    m = re.search(r"(\d+)\s*h", s)
    if m:
        total += int(m.group(1)) * 60
    m = re.search(r"(\d+)\s*m", s)
    if m:
        total += int(m.group(1))
    if total:
        return total
    m = re.search(r"(\d+)", s)
    return float(m.group(1)) if m else None


ics_text = (ROOT / "calendar_events.ics").read_text(encoding="utf-8", errors="replace")
lines = unfold_ics(ics_text)
events = []
in_event = False
current = []
for line in lines:
    if line == "BEGIN:VEVENT":
        in_event = True
        current = []
    elif line == "END:VEVENT" and in_event:
        props = {}
        for ln in current:
            if ":" not in ln:
                continue
            prop, val = ln.split(":", 1)
            name, params = parse_params(prop)
            props.setdefault(name, []).append((val, params))
        events.append(props)
        in_event = False
    elif in_event:
        current.append(line)

all_starts = []
for ev in events:
    if "DTSTART" in ev:
        dt, _ = parse_ics_dt(ev["DTSTART"][0][0], ev["DTSTART"][0][1])
        all_starts.append(dt)
cap_date = max(dt.astimezone(NY).date() for dt in all_starts) if all_starts else date(2026, 5, 6)

calendar_count = 0
for ev in events:
    uid = ev.get("UID", [(None, {})])[0][0]
    summary = ev.get("SUMMARY", [(None, {})])[0][0]
    location = ev.get("LOCATION", [(None, {})])[0][0]
    description = ev.get("DESCRIPTION", [(None, {})])[0][0]
    status = ev.get("STATUS", [(None, {})])[0][0]
    dtstart, all_day = parse_ics_dt(ev["DTSTART"][0][0], ev["DTSTART"][0][1])
    dtend = None
    if "DTEND" in ev:
        dtend, _ = parse_ics_dt(ev["DTEND"][0][0], ev["DTEND"][0][1])
    else:
        dtend = dtstart
    duration = dtend - dtstart
    rrule_raw = ev.get("RRULE", [(None, {})])[0][0]
    rrule = parse_rrule(rrule_raw)
    until = None
    if rrule.get("UNTIL"):
        until, _ = parse_ics_dt(rrule["UNTIL"], {})
    exdates = set()
    for exval, exparams in ev.get("EXDATE", []):
        for one in exval.split(","):
            exdt, _ = parse_ics_dt(one, exparams)
            exdates.add(exdt)

    occs = []
    if not rrule:
        occs = [dtstart]
    else:
        freq = rrule.get("FREQ")
        interval = int(rrule.get("INTERVAL", "1"))
        start_local = dtstart.astimezone(NY)
        bydays = rrule.get("BYDAY")
        if freq == "DAILY":
            d = start_local.date()
            while d <= cap_date:
                days_since = (d - start_local.date()).days
                if days_since >= 0 and days_since % interval == 0:
                    occ = datetime.combine(d, start_local.timetz().replace(tzinfo=None), tzinfo=NY).astimezone(UTC)
                    occs.append(occ)
                d += timedelta(days=1)
        elif freq == "WEEKLY":
            wanted = [weekday_num(x) for x in (bydays.split(",") if bydays else [start_local.strftime("%a")[:2].upper()])]
            d = start_local.date()
            while d <= cap_date:
                weeks_since = (d - start_local.date()).days // 7
                if d >= start_local.date() and weeks_since % interval == 0 and d.weekday() in wanted:
                    occ = datetime.combine(d, start_local.timetz().replace(tzinfo=None), tzinfo=NY).astimezone(UTC)
                    occs.append(occ)
                d += timedelta(days=1)
        elif freq == "MONTHLY":
            y, m = start_local.year, start_local.month
            month_index = 0
            while date(y, m, 1) <= cap_date.replace(day=1):
                if month_index % interval == 0:
                    tokens = bydays.split(",") if bydays else [str((start_local.day - 1) // 7 + 1) + start_local.strftime("%a")[:2].upper()]
                    for tok in tokens:
                        od = nth_weekday(y, m, tok)
                        if od and od >= start_local.date() and od <= cap_date:
                            occ = datetime.combine(od, start_local.timetz().replace(tzinfo=None), tzinfo=NY).astimezone(UTC)
                            occs.append(occ)
                month_index += 1
                if m == 12:
                    y += 1; m = 1
                else:
                    m += 1
        else:
            occs = [dtstart]
    occs = sorted(set(o for o in occs if o not in exdates and (until is None or o <= until) and o.astimezone(NY).date() <= cap_date))
    for seq, occ_start in enumerate(occs, 1):
        calendar_count += 1
        occ_end = occ_start + duration
        row = base_row(occ_start, "calendar_events.ics", "calendar", "calendar_event", f"calendar:{uid}:{seq}", occ_start, occ_end, inferred=all_day)
        row.update({
            "calendar_uid": uid,
            "calendar_summary": summary,
            "calendar_location": location,
            "calendar_description": description,
            "calendar_status": status,
            "calendar_is_recurring": bool(rrule_raw),
            "calendar_recurrence_rule": rrule_raw,
            "calendar_occurrence_sequence": seq,
            "calendar_duration_min": duration.total_seconds() / 60 if duration else None,
            "calendar_is_all_day": bool(all_day),
        })
        rows.append(row)


# GP visit notes.
